    /// Decision **G1** (`ah-q6bt`), and the reversal of what shipped before: an army of 90 armed
    /// men standing in the hex having ordered nothing does **not** carry a lone leader over the
    /// threshold. Before this bead the leader was credited the whole 17,926 on their strength,
    /// which is the outcome the navigator said they did not want.
    #[test]
    fn a_bystanders_men_do_not_carry_the_pillage() {
        let hex_region = ReportRegion {
            tax_base: Some(8963),
            ..region(vec![
                with_silver(unit("683"), 0),
                armed_to_pillage(with_silver(unit("684"), 0), 8963),
            ])
        };
        let review = review_turn(
            &report(vec![hex_region]),
            "unit 683\nPILLAGE\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        let row = review
            .silver
            .iter()
            .find(|row| row.unit_id == "683")
            .expect("priced");
        assert_eq!(row.income, Some(0));
        assert_eq!(row.doubt, None);
    }

    /// Decisions **G1** and **D1** together: the army that *does* order `PILLAGE` carries the hex,
    /// and the take is divided between the two in proportion to their combat ready men - so the
    /// leader takes nothing at all, having none, and the army takes the lot.
    #[test]
    fn the_men_are_counted_across_the_pillagers_and_the_take_divided_between_them() {
        let hex_region = ReportRegion {
            tax_base: Some(8963),
            ..region(vec![
                with_silver(unit("683"), 0),
                armed_to_pillage(with_silver(unit("684"), 0), 8963),
            ])
        };
        let review = review_turn(
            &report(vec![hex_region]),
            "unit 683\nPILLAGE\nunit 684\nPILLAGE\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        let earned = |unit_id: &str| {
            review
                .silver
                .iter()
                .find(|row| row.unit_id == unit_id)
                .expect("priced")
                .income
        };
        assert_eq!(earned("683"), Some(0), "no combat ready men, no share");
        assert_eq!(earned("684"), Some(17_926), "all 90 of the ready men");
    }

    /// A guessed headcount among the *pillagers* leaves the threshold unanswerable - the estimate
    /// might be what carries them over it. A guess anywhere else in the hex no longer says
    /// anything at all, which is decision G1 (`ah-q6bt`).
    #[test]
    fn a_guessed_headcount_among_the_pillagers_doubts_the_pillage() {
        let mut guessed = armed_to_pillage(with_silver(unit("684"), 0), 8963);
        guessed.men_estimated = true;
        let hex_region = ReportRegion {
            tax_base: Some(8963),
            ..region(vec![with_silver(unit("683"), 0), guessed])
        };
        let review = review_turn(
            &report(vec![hex_region]),
            "unit 683\nPILLAGE\nunit 684\nPILLAGE\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        let row = review
            .silver
            .iter()
            .find(|row| row.unit_id == "683")
            .expect("priced");
        assert_eq!(row.doubt, Some(SilverDoubt::UnknownCombatReady));
        assert_eq!(row.income, None);
    }

    /// The pair is the point (`ah-abwx`, and the reason `ah-ycuj` exists): a faction short of the
    /// men must be shown nothing by the column *and* charged nothing by the ledger, or the player
    /// gets a silent `not-enough-silver` beside a column that promised the silver.
    #[test]
    fn the_ledger_and_the_column_agree_about_pillage() {
        let spend = |units: Vec<ReportUnit>, orders: &str| {
            let hex_region = ReportRegion {
                tax_base: Some(8963),
                for_sale: vec![MarketItem {
                    amount: 100,
                    name: "grain".to_string(),
                    tag: "GRAI".to_string(),
                    price: 100,
                }],
                ..region(units)
            };
            review_turn(
                &report(vec![hex_region]),
                orders,
                Some(&ruleset()),
                CheckOptions::default(),
            )
        };

        // Without the men the pillage buys nothing, so both surfaces say so.
        let broke = spend(
            vec![with_silver(unit("683"), 0)],
            "unit 683\nPILLAGE\nBUY 10 grain\n",
        );
        // Nothing is affordable, so nothing is bought; the ask survives as `wanted_for_orders`,
        // which is what the warning is measured against (`ah-omn7`).
        assert_eq!(broke.silver[0].at_month_end, Some(0));
        assert_eq!(broke.silver[0].wanted_for_orders, Some(1000));
        assert!(
            broke
                .findings
                .iter()
                .any(|finding| finding.code == codes::NOT_ENOUGH_SILVER),
            "the warning fires too: {:?}",
            codes(&broke.findings)
        );

        // With them, both surfaces credit the pillage and neither complains.
        let paid = spend(
            vec![armed_to_pillage(with_silver(unit("683"), 0), 8963)],
            "unit 683\nPILLAGE\nBUY 10 grain\n",
        );
        assert!(
            paid.silver[0].at_month_end.is_some_and(|end| end > 0),
            "the column shows the pillage: {:?}",
            paid.silver[0].at_month_end
        );
        assert!(
            !paid
                .findings
                .iter()
                .any(|finding| finding.code == codes::NOT_ENOUGH_SILVER),
            "the warning stays quiet: {:?}",
            codes(&paid.findings)
        );
    }

    /// The column has always counted what an earning spell raises; the ledger never did, so a mage
    /// spending the proceeds was warned about money it will have (`ah-lu0f.3`).
    #[test]
    fn a_mage_casting_an_earning_spell_can_spend_what_it_raises() {
        let hex_region = ReportRegion {
            entertainment: Some(5000),
            for_sale: vec![MarketItem {
                amount: 100,
                name: "grain".to_string(),
                tag: "GRAI".to_string(),
                price: 100,
            }],
            ..region(vec![with_skill(with_silver(unit("683"), 0), "PHEN", 2)])
        };
        let review = review_turn(
            &report(vec![hex_region]),
            "unit 683\nCAST Phantasmal_Entertainment\nBUY 10 grain\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        assert!(
            !review
                .findings
                .iter()
                .any(|finding| finding.code == codes::NOT_ENOUGH_SILVER),
            "the cast pays for the grain: {:?}",
            codes(&review.findings)
        );
    }

    /// Narrowing `cast`'s cost loop and adding the shared charge is exactly the edit that charges
    /// silver twice, and nothing else would notice (`ah-lu0f.3`). `ah-ofpb.4`: the mage is now
    /// funded for every item its level makes, not for one - the committed ruleset's first spell in
    /// tag order with a `SILV` cost is `CFSW`, 60 percent per level, so a level 5 mage makes 3.
    #[test]
    fn a_cast_is_not_charged_twice_for_its_silver() {
        let spell = ruleset()
            .skills
            .iter()
            .find(|(_, skill)| {
                skill.cast.as_ref().is_some_and(|cast| {
                    cast.costs
                        .iter()
                        .any(|input| input.tag.eq_ignore_ascii_case(SILVER) && input.amount > 0)
                })
            })
            .map(|(_, skill)| skill.clone())
            .expect("the committed ruleset prices at least one cast in silver");
        let cast_cost = spell.cast.as_ref().expect("a cast cost");
        let cost: i64 = cast_cost
            .costs
            .iter()
            .filter(|input| input.tag.eq_ignore_ascii_case(SILVER))
            .map(|input| input.amount)
            .sum();
        let wanted = plan_cast(
            cast_cost,
            &Caster {
                skills: &[],
                held: &[],
                silver_available: i64::MAX,
                transmuting: None,
            },
            5,
        )
        .wanted;

        let hex_region = region(vec![with_skill(
            with_silver(unit("683"), cost * wanted),
            &spell.tag,
            5,
        )]);
        let review = review_turn(
            &report(vec![hex_region]),
            &format!("unit 683\nCAST {}\n", spell.name.replace(' ', "_")),
            Some(&ruleset()),
            CheckOptions::default(),
        );

        assert!(
            !review
                .findings
                .iter()
                .any(|finding| finding.code == codes::NOT_ENOUGH_SILVER),
            "exactly the cost is charged, not twice it: {:?}",
            codes(&review.findings)
        );
    }

