    /// `own_unit_pillages` takes a hex, and this is what proves it was not hoisted to the report.
    #[test]
    fn a_pillage_in_one_hex_does_not_empty_another() {
        let here = ReportRegion {
            tax_base: Some(2500),
            ..region_at("1:7,53", 7, 53, vec![with_silver(unit("1"), 0)])
        };
        let mut elsewhere = ReportRegion {
            tax_base: Some(2500),
            ..region_at(
                "1:9,53",
                9,
                53,
                vec![with_skill(with_silver(unit("2"), 0), "COMB", 1)],
            )
        };
        for unit in &mut elsewhere.units {
            unit.region_id = "1:9,53".to_string();
        }

        let review = review_turn(
            &report(vec![here, elsewhere]),
            "unit 1\nPILLAGE\n\nunit 2\nTAX\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        let taxer = review
            .silver
            .iter()
            .find(|row| row.unit_id == "2")
            .expect("the taxer is priced");
        assert_eq!(
            taxer.income,
            Some(50),
            "another hex's pillage is not its own"
        );
        assert!(
            !review
                .findings
                .iter()
                .any(|finding| finding.code == codes::TAXED_A_PILLAGED_HEX),
            "and it is told nothing: {:?}",
            codes(&review.findings)
        );
    }

    /// The predicate is about the hex, not about other units, so a second unit taxing the hex the
    /// first pillages is warned about its own `TAX` line - the pillage is fine, the tax collects
    /// nothing.
    ///
    /// `rules/pillage` and `rules/tax` each spend the unit's month, so the *pillager's* own
    /// replaced `TAX` never runs and is told so once, by `two-month-long-orders`, rather than
    /// warned about a collection it will not attempt (`ah-rzkm`, `ah-728m.2.1`).
    #[test]
    fn a_second_unit_taxing_a_pillaged_hex_is_still_told() {
        let hex_region = ReportRegion {
            tax_base: Some(2500),
            ..region(vec![
                armed_to_pillage(with_silver(unit("1"), 0), 2500),
                with_silver(unit("2"), 0),
            ])
        };
        let review = review_turn(
            &report(vec![hex_region]),
            "unit 1\nTAX\nPILLAGE\nunit 2\nTAX\n",
            Some(&ruleset()),
            CheckOptions::default(),
        );

        let told: Vec<&Finding> = review
            .findings
            .iter()
            .filter(|finding| finding.code == codes::TAXED_A_PILLAGED_HEX)
            .collect();
        assert_eq!(told.len(), 1, "on the taxing unit's line: {told:?}");
        assert_eq!(told[0].unit_id.as_deref(), Some("2"));
        assert!(
            review
                .findings
                .iter()
                .any(|finding| finding.code == codes::TWO_MONTH_LONG_ORDERS
                    && finding.unit_id.as_deref() == Some("1")),
            "the pillager's own TAX is told it will not run: {:?}",
            codes(&review.findings)
        );

        let row = review
            .silver
            .iter()
            .find(|row| row.unit_id == "1")
            .expect("priced");
        assert_eq!(row.income, Some(5000), "the pillage still pays");
    }

