    // --- fixtures ---------------------------------------------------------------------------

    fn region(units: Vec<ReportUnit>) -> ReportRegion {
        ReportRegion {
            region_id: "1:7,53".to_string(),
            coordinate: Coordinate { x: 7, y: 53, z: 1 },
            terrain: "mountain".to_string(),
            province: "Inhead".to_string(),
            population: Some(1000),
            race: Some("humans".to_string()),
            units,
            ..Default::default()
        }
    }

    /// A region with the given id, so a test can order things in several at once.
    fn region_at(id: &str, x: i32, y: i32, units: Vec<ReportUnit>) -> ReportRegion {
        ReportRegion {
            region_id: id.to_string(),
            coordinate: Coordinate { x, y, z: 1 },
            ..region(units)
        }
    }

    fn unit(id: &str) -> ReportUnit {
        with_men(
            ReportUnit {
                unit_id: id.to_string(),
                name: format!("Unit {id}"),
                region_id: "1:7,53".to_string(),
                faction_id: Some("95".to_string()),
                faction_name: Some("Ours".to_string()),
                own: true,
                men: 1,
                men_by_race: vec![],
                // The checks that price a study are entitled to an exact headcount, so the fixtures
                // give them one; `an_estimated_headcount_prices_no_study` covers the other case.
                men_estimated: false,
                // Every unit owes maintenance now (`ah-1wcw.4`), and a fixture that did not pay it
                // would warn `not-enough-silver` in a hundred tests about something else. These
                // fixtures feed themselves: the flag and the grain pay the fee in food, so no
                // fixture's *silver* moves and every existing assertion still means what it did.
                flags: vec!["consuming unit's food".to_string()],
                items: vec![ItemAmount {
                    amount: 1,
                    name: "grain".to_string(),
                    tag: "GRAI".to_string(),
                }],
                ..Default::default()
            },
            1,
        )
    }

    /// A fixture unit with its maintenance grain taken away again, for the handful of tests that
    /// weigh or move everything a unit carries and would otherwise weigh the grain too. It pays
    /// its maintenance in silver instead - which weighs nothing, so no fleet's load moves.
    fn unfed(unit: ReportUnit) -> ReportUnit {
        with_silver(starving(unit), 10_000)
    }

    /// A fixture unit with neither its maintenance grain nor any silver to pay the fee with, for
    /// the tests that are *about* a unit that cannot pay its own upkeep.
    fn starving(mut unit: ReportUnit) -> ReportUnit {
        unit.items
            .retain(|item| !item.tag.eq_ignore_ascii_case("GRAI"));
        unit.flags.clear();
        unit
    }

    fn with_silver(mut unit: ReportUnit, amount: i64) -> ReportUnit {
        unit.items.push(ItemAmount {
            amount,
            name: "silver".to_string(),
            tag: SILVER.to_string(),
        });
        unit
    }

    fn with_flag(mut unit: ReportUnit, flag: &str) -> ReportUnit {
        unit.flags.push(flag.to_string());
        unit
    }

    /// Gives the unit this much of the goods - *replacing* any line it already carries for the
    /// tag rather than adding a second one. `unit` already hands out a grain, so pushing
    /// unconditionally left fixtures holding two `GRAI` lines, which the two silver surfaces then
    /// read differently: `Ordered::holding` takes the first match and the ledger's balance map
    /// takes the last (`ah-lu0f.2`). A real report never lists a tag twice.
    fn with_item(mut unit: ReportUnit, amount: i64, name: &str, tag: &str) -> ReportUnit {
        unit.items
            .retain(|item| !item.tag.eq_ignore_ascii_case(tag));
        unit.items.push(ItemAmount {
            amount,
            name: name.to_string(),
            tag: tag.to_string(),
        });
        unit
    }

    fn with_people(mut unit: ReportUnit, people: Vec<ItemAmount>) -> ReportUnit {
        assert!(people.iter().all(|person| person.amount >= 0));
        let old_tags: Vec<String> = unit
            .men_by_race
            .iter()
            .map(|person| person.tag.to_ascii_lowercase())
            .collect();
        unit.items.retain(|item| {
            !old_tags
                .iter()
                .any(|tag| item.tag.eq_ignore_ascii_case(tag))
        });
        let people: Vec<ItemAmount> = people
            .into_iter()
            .filter(|person| person.amount != 0)
            .collect();
        unit.men = people.iter().map(|person| person.amount).sum();
        unit.men_by_race = people.clone();
        unit.items.extend(people);
        unit
    }

    /// Enough armed men to pillage a hex of this tax base - the threshold exactly, each with a
    /// sword, which is a weapon anyone may wield (`ah-1ad6.2`).
    fn armed_to_pillage(unit: ReportUnit, tax_base: i64) -> ReportUnit {
        let men = pillage_threshold(tax_base);
        with_item(with_men(unit, men), men, "sword", "SWOR")
    }

    fn with_men(mut unit: ReportUnit, men: i64) -> ReportUnit {
        unit = with_people(
            unit,
            if men == 0 {
                vec![]
            } else {
                vec![ItemAmount {
                    amount: men,
                    name: "human".to_string(),
                    tag: "HUMN".to_string(),
                }]
            },
        );
        // More men owe more maintenance, so a fixture that feeds itself has to feed all of them -
        // one grain for each 50 silver owed (`rules/economy_maintenance`), or the fee
        // spills over into silver and warns.
        for item in &mut unit.items {
            if item.tag.eq_ignore_ascii_case("GRAI") {
                item.amount = (men * 10 + 49) / 50;
            }
        }
        unit
    }

    fn with_race(unit: ReportUnit, men: i64, name: &str, tag: &str) -> ReportUnit {
        let unit = with_people(
            unit,
            if men == 0 {
                vec![]
            } else {
                vec![ItemAmount {
                    amount: men,
                    name: name.to_string(),
                    tag: tag.to_string(),
                }]
            },
        );
        with_men_grain(unit, men)
    }

    fn with_men_grain(mut unit: ReportUnit, men: i64) -> ReportUnit {
        for item in &mut unit.items {
            if item.tag.eq_ignore_ascii_case("GRAI") {
                item.amount = (men * 10 + 29) / 30;
            }
        }
        unit
    }

    fn with_skill(mut unit: ReportUnit, tag: &str, level: u32) -> ReportUnit {
        unit.skills.push(Skill {
            name: tag.to_lowercase(),
            tag: tag.to_string(),
            level,
            points: 0,
        });
        unit
    }

    #[test]
    fn fixture_helpers_keep_exact_headcounts_backed_by_people_items() {
        for unit in [
            unit("1"),
            with_men(unit("2"), 6),
            with_race(unit("3"), 4, "orcs", "ORC"),
            with_men(unit("4"), 0),
        ] {
            let (races, total) = composition::men_in(&unit.items, &ruleset());
            assert_eq!(races, unit.men_by_race);
            assert_eq!(total, unit.men);
            for person in &unit.men_by_race {
                assert_eq!(
                    unit.items
                        .iter()
                        .filter(|item| item.tag.eq_ignore_ascii_case(&person.tag))
                        .count(),
                    1
                );
            }
        }
    }

    /// A longship, stated exactly as the fixture reports write one: `Load: 110/150; Sailors:
    /// 4/4; MaxSpeed: 4.`
    fn longship(structure_id: &str) -> Structure {
        Structure {
            structure_id: structure_id.to_string(),
            name: "Ship".to_string(),
            kind: "Longship".to_string(),
            description: Some("Load: 110/150; Sailors: 4/4; MaxSpeed: 4.".to_string()),
            needs: None,
            ..Default::default()
        }
    }

    fn sail(level: u32) -> Skill {
        Skill {
            name: "sailing".to_string(),
            tag: "SAIL".to_string(),
            level,
            points: 15 * level * (level + 1),
        }
    }

    /// `sail`'s points must imply its level under `level_for_points`, or every crew merge built on
    /// this fixture would drop the skill at 0 points and pass for the wrong reason.
    #[test]
    fn the_sail_fixture_carries_the_points_its_level_implies() {
        assert_eq!(sail(1).points, 30);
        assert_eq!(sail(2).points, 90);
        assert_eq!(sail(3).points, 180);
        assert_eq!(sail(4).points, 300);
    }

    fn report(regions: Vec<ReportRegion>) -> ParsedReport {
        ParsedReport {
            regions,
            ..Default::default()
        }
    }

    /// `report`, with a `Faction Status:` block carrying one `label: used (maximum)` entry - what
    /// the faction-wide checks read instead of anything counted per hex.
    fn report_with_status(
        label: &str,
        used: i64,
        maximum: i64,
        regions: Vec<ReportRegion>,
    ) -> ParsedReport {
        ParsedReport {
            header: crate::report::header::ReportHeader {
                faction_status: crate::report::header::FactionStatus {
                    entries: vec![crate::report::header::FactionStatusEntry {
                        label: label.to_string(),
                        used,
                        maximum,
                    }],
                    ..Default::default()
                },
                ..Default::default()
            },
            regions,
            ..Default::default()
        }
    }

    /// Runs the checks with the committed ruleset, which is what the shell serves.
    /// The runtime default, with `unit-does-nothing` and `two-month-long-orders` off.
    ///
    /// Nearly every fixture below stands up a unit to exercise one check and gives it only the
    /// orders that check is about - a GIVE, a BUY, a bare block - so on the real default this check
    /// fires on almost all of them and buries what each test is actually asserting. Exactly the
    /// shape `check_ignoring_transfer_targets` below was written for when `give-target-not-here`
    /// arrived. The check's own fixtures use `check_idle` above, and
    /// `every_advisory_code_can_be_silenced` runs fully enabled.
    ///
    /// `two-month-long-orders` is off here for the same reason: a fixture written for another
    /// check often gives one unit a `MOVE` and a `STUDY`, or two `STUDY` lines, because that is
    /// the smallest way to exercise what it is about - and the finding then buries the assertion.
    /// The check's own fixtures use `check_months`.
    fn check(regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(&ruleset()),
            disabling_all(&[codes::UNIT_DOES_NOTHING, codes::TWO_MONTH_LONG_ORDERS]),
        )
    }

    /// `check`, against a ruleset the test has altered - the only way to stand up a catalogue that
    /// states no race limits, since the committed one states them for every race (`ah-9hp7.2`).
    fn check_against(ruleset: &Ruleset, regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(ruleset),
            disabling_all(&[codes::UNIT_DOES_NOTHING, codes::TWO_MONTH_LONG_ORDERS]),
        )
    }

    /// `check`, with `give-target-not-here` also disabled.
    ///
    /// A raft of resource-ledger fixtures below give or take from unit numbers ("7", "999", ...)
    /// chosen only to be absent from the report - that is what lets them test "a recipient outside
    /// the hex is not credited" without also standing up a whole second region. `give-target-not-here`
    /// is built for exactly that shape and now fires on every one of them; real, but not what these
    /// tests are about, so it is turned off here rather than folded into every fixture below.
    fn check_ignoring_transfer_targets(regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(&ruleset()),
            disabling_all(&[codes::GIVE_TARGET_NOT_HERE, codes::UNIT_DOES_NOTHING]),
        )
    }

    /// `check`, with both of the "this BUILD builds nothing" checks disabled.
    ///
    /// A run of fixtures below order a bare `BUILD` from a unit standing in nothing, or a
    /// `BUILD HELP` naming a unit with no orders, only to have *something* in the block -
    /// `already-built`'s helper cases, a unit that is busy rather than teaching, a BUILD that is
    /// not a PRODUCE. `build-outside-structure` and `build-help-not-building` are real on every
    /// one of them, and are pinned by their own tests; they are turned off here rather than
    /// folded into fixtures that are about something else.
    fn check_ignoring_empty_builds(regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(&ruleset()),
            disabling_all(&[
                codes::BUILD_OUTSIDE_STRUCTURE,
                codes::BUILD_HELP_NOT_BUILDING,
                codes::UNIT_DOES_NOTHING,
                codes::TWO_MONTH_LONG_ORDERS,
            ]),
        )
    }

    /// `check`, with `build-without-skill` also disabled.
    ///
    /// The fixtures for the other three BUILD checks stand a unit up with no skills at all and put
    /// it to work on a Timber Yard, a Stockade or a Tower - every one of which states a
    /// requirement, so every one of them newly warns, correctly and beside the point. Turned off
    /// here rather than skilling up a dozen fixtures written about something else, and rather than
    /// softening the new check until they go quiet (`docs/retrospectives/ah-vkut.md`, second
    /// section, is about exactly that temptation).
    fn check_ignoring_build_skill(regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(&ruleset()),
            disabling_all(&[codes::BUILD_WITHOUT_SKILL, codes::UNIT_DOES_NOTHING]),
        )
    }

    fn codes(findings: &[Finding]) -> Vec<&str> {
        findings
            .iter()
            .map(|finding| finding.code.as_str())
            .collect()
    }

    /// The `Code` newtype is the string the shell, the settings and the diagnostics all know -
    /// constructible only through `codes::*`, so a finding can no longer be emitted under a bare
    /// literal missing from `codes::ALL` (ah-m9q.2's `teacher-has-free-slots` gap).
    #[test]
    fn a_code_is_the_string_the_shell_and_the_settings_know() {
        let code: Code = codes::HEX_UNGUARDED;
        assert_eq!(code.as_str(), "hex-unguarded");
        assert_eq!(code.to_string(), "hex-unguarded");
    }

    /// The hex-anchored finding among several, for a pooled fixture that also emits
    /// `part-of-hex-shortfall` pointers at the lines claiming against the pool (`ah-eurs`).
    fn hex_anchored(findings: Vec<Finding>) -> Finding {
        let mut hex_findings = findings.iter().filter(|finding| finding.unit_id.is_none());
        let finding = hex_findings
            .next()
            .unwrap_or_else(|| panic!("expected a hex-anchored finding: {findings:?}"))
            .clone();
        assert!(
            hex_findings.next().is_none(),
            "expected one hex-anchored finding: {findings:?}"
        );
        finding
    }

    fn only(findings: Vec<Finding>) -> Finding {
        assert_eq!(findings.len(), 1, "expected one finding: {findings:?}");
        findings.into_iter().next().expect("just counted")
    }

    // --- what spends the month ---------------------------------------------------------------

    #[test]
    fn teaching_spends_the_month() {
        assert!(spends_the_month(&Intent::Teach {
            students: Vec::new()
        }));
    }

    /// The rules: "a CAST order is not a full month order; a mage may still MOVE, STUDY, or use
    /// any other month long order."
    #[test]
    fn casting_does_not_spend_the_month() {
        assert!(!spends_the_month(&Intent::Cast {
            spell: "Fire".to_string(),
            arguments: Vec::new(),
        }));
    }

    /// A bare `CAST` falls back to `MonthLong("CAST")`, which must be caught before the general
    /// `MonthLong` arm or the correction silently does not apply to it.
    #[test]
    fn a_bare_cast_does_not_spend_the_month() {
        assert!(!spends_the_month(&Intent::MonthLong("CAST")));
    }

    #[test]
    fn idling_spends_the_month() {
        assert!(spends_the_month(&Intent::MonthLong("IDLE")));
    }

    #[test]
    fn annihilating_spends_the_month() {
        assert!(spends_the_month(&Intent::MonthLong("ANNIHILATE")));
    }

    #[test]
    fn giving_does_not_spend_the_month() {
        assert!(!spends_the_month(&Intent::Give {
            to: Party::Unit("4022".to_string()),
            what: Selector::Item("SILV".to_string()),
            amount: Amount::Exact(10),
        }));
    }

    /// The `is_busy` rewrite must leave the teaching check exactly as it was. `is_busy` excludes
    /// `Intent::Teach` on purpose, so a unit already teaching is *not* counted as busy and is still
    /// weighed for spare teaching capacity - which is the whole point of that exclusion. If this
    /// stops firing, the rewrite folded teaching into "busy" and broke the teaching check.
    #[test]
    fn a_teaching_unit_is_still_weighed_for_spare_capacity() {
        let findings = check(
            vec![region(vec![
                with_leaders(with_skill(unit("1"), "COMB", 2), 1),
                unit("2"),
                unit("3"),
            ])],
            concat!(
                "unit 1\nTEACH 2\n",
                "unit 2\nSTUDY COMB\n",
                "unit 3\nSTUDY COMB\n",
            ),
        );
        assert!(
            codes(&findings).contains(&codes::TEACHER_HAS_FREE_SLOTS.as_str()),
            "{findings:?}"
        );
    }

    // --- two orders for one month (ah-o7td) ---------------------------------------------------

    /// `check`, with `two-month-long-orders` left on - it is what these fixtures are about.
    fn check_months(regions: Vec<ReportRegion>, orders: &str) -> Vec<Finding> {
        check_turn(
            &report(regions),
            orders,
            Some(&ruleset()),
            disabling(codes::UNIT_DOES_NOTHING),
        )
    }

    /// Only the `two-month-long-orders` findings, so a fixture's other advice cannot mask what
    /// these tests are about.
    fn two_month_long(findings: Vec<Finding>) -> Vec<Finding> {
        findings
            .into_iter()
            .filter(|finding| finding.code == codes::TWO_MONTH_LONG_ORDERS)
            .collect()
    }

    /// `rules/form`: the new unit inherits its parent's flags "with the exception of the guard and
    /// autotax flags" - so a formed unit is never told it is set to tax, whatever its parent is.
    #[test]
    fn a_formed_unit_is_not_told_its_parents_autotax_loses_the_month() {
        let findings = two_month_long(check_months(
            vec![region(vec![with_flag(unit("900"), "taxing"), unit("901")])],
            "unit 900\nFORM 1\nSTUDY COMBAT\nEND\nTAX\nunit 901\nMOVE N\nSTUDY COMBAT\n",
        ));

        assert!(
            findings
                .iter()
                .any(|finding| finding.unit_id == Some("901".to_string())),
            "the control unit proves the check is on: {findings:?}"
        );
        assert!(
            !findings
                .iter()
                .any(|finding| finding.unit_id == Some("new-1".to_string())),
            "the formed unit inherits no autotax, so its STUDY beats nothing: {findings:?}"
        );
    }

    #[test]
    fn an_earlier_month_long_order_is_marked_naming_the_final_one() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nSTUDY Combat\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(finding.unit_id, Some("683".to_string()));
        assert_eq!(
            finding.message,
            "STUDY replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
    }

    /// The navigator's wording, on the example they chose it for.
    #[test]
    fn a_replaced_build_is_marked_naming_the_produce_that_replaces_it() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nBUILD Tower\nPRODUCE sword\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "PRODUCE replaces this BUILD as the unit's month-long order, so this BUILD will not run"
        );
    }

    /// A chain broken by another month-long order is two losers and one winner, and the chain's
    /// first leg is marked on its own line.
    #[test]
    fn an_interrupted_movement_chain_marks_both_earlier_segments() {
        let findings = two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nSTUDY Combat\nMOVE S\n",
        ));
        assert_eq!(findings.len(), 2, "{findings:?}");
        assert_eq!(findings[0].line, Some(2));
        assert_eq!(
            findings[0].message,
            "MOVE replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
        assert_eq!(findings[1].line, Some(3));
        assert_eq!(
            findings[1].message,
            "MOVE replaces this STUDY as the unit's month-long order, so this STUDY will not run"
        );
    }

    /// A chained journey lost the month once, not once per leg, so the whole segment is marked on
    /// the line that opens it.
    #[test]
    fn a_replaced_movement_chain_is_marked_once() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nMOVE NE\nSTUDY Combat\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "STUDY replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
    }

    /// `rules/move`: "Multiple MOVE orders given by one unit will chain together."
    #[test]
    fn two_move_lines_are_one_journey() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![unit("683")])],
                "unit 683\nMOVE N\nMOVE NE\n",
            )),
            vec![]
        );
    }

    /// `rules/teach`: "Subsequent TEACH orders can be used to add units to be taught."
    #[test]
    fn two_teach_lines_are_one_teaching() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![unit("683")])],
                "unit 683\nTEACH NEW 2\nTEACH 5104\n",
            )),
            vec![]
        );
    }

    /// `rules/sail` gives `SAIL N` / `SAIL NW` on separate lines as one route.
    #[test]
    fn two_sail_lines_are_one_route() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![unit("683")])],
                "unit 683\nSAIL N\nSAIL NW\n",
            )),
            vec![]
        );
    }

    /// Walking and sailing are two journeys, not one - the rules say nothing either way, and this
    /// is the navigator's decision of 2026-08-29.
    #[test]
    fn move_and_sail_are_two_journeys() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nSAIL NW\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "SAIL replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
    }

    /// Nothing in the rules lets STUDY chain the way MOVE and TEACH explicitly do, so the second
    /// line is a wasted one - and says so with the same word twice, which is accurate.
    #[test]
    fn two_study_lines_are_two_claims_on_the_month() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nSTUDY Combat\nSTUDY Longbow\n",
        )));
        assert_eq!(
            finding.message,
            "STUDY replaces this STUDY as the unit's month-long order, so this STUDY will not run"
        );
    }

    /// `rules/magic_usingmagic`: "a CAST order is not a full month order; a mage may still MOVE,
    /// STUDY, or use any other month long order." This check inherits that from
    /// `spends_the_month`; the test pins that it does.
    #[test]
    fn a_cast_beside_a_month_long_order_is_not_a_second() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![unit("683")])],
                "unit 683\nCAST Earth_Lore\nSTUDY Earth_Lore\n",
            )),
            vec![]
        );
    }

    #[test]
    fn giving_and_buying_beside_a_month_long_order_are_not_a_second() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![unit("683")])],
                "unit 683\nGIVE 5104 100 SILV\nBUY 5 HORS\nGUARD 1\nSTUDY Combat\n",
            )),
            vec![]
        );
    }

    /// Every earlier order is marked against the *last*, not against the one below it: the last is
    /// the one that will run, so it is the one each loss is measured from.
    #[test]
    fn every_order_before_the_last_is_marked_against_it() {
        let findings = two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nBUILD Tower\nENTERTAIN\n",
        ));
        assert_eq!(findings.len(), 2, "{findings:?}");
        assert_eq!(findings[0].line, Some(2));
        assert_eq!(
            findings[0].message,
            "ENTERTAIN replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
        assert_eq!(findings[1].line, Some(3));
        assert_eq!(
            findings[1].message,
            "ENTERTAIN replaces this BUILD as the unit's month-long order, so this BUILD will \
             not run"
        );
    }

    /// The navigator's decision of 2026-08-29: the flag is a claimant, and a written month-long
    /// order beats it. This is what `silver::taxes` has already forecast since `ah-v8zh`; the
    /// finding says it out loud.
    #[test]
    fn a_flagged_taxer_given_work_is_told_it_will_not_tax() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![taxing_by_flag(unit("683"))])],
            "unit 683\nWORK\n",
        )));
        assert_eq!(finding.line, Some(1));
        assert_eq!(finding.column_start, None);
        assert_eq!(finding.column_end, None);
        assert_eq!(
            finding.message,
            "set to tax every month, but WORK spends the month instead, so it will not tax"
        );
    }

    /// A block with its own `TAX` is not also told about the flag: the tax it names is the one the
    /// ordinary wording is already about. The navigator chose one warning here, on the replaced
    /// `TAX` line, rather than that line-level finding plus the block-level flag warning.
    #[test]
    fn a_replaced_written_tax_does_not_duplicate_the_tax_flag_warning() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![taxing_by_flag(unit("683"))])],
            "unit 683\nTAX\nWORK\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "WORK replaces this TAX as the unit's month-long order, so this TAX will not run"
        );
    }

    /// The flag alone is one claimant, not two - a flagged unit with a free month taxes, which is
    /// exactly what it was set to do.
    #[test]
    fn a_flagged_taxer_with_nothing_else_to_do_is_left_alone() {
        assert_eq!(
            two_month_long(check_months(
                vec![region(vec![taxing_by_flag(unit("683"))])],
                "unit 683\n",
            )),
            vec![]
        );
    }

    /// Both losses are measured from the last written order. The hex re-sorts its findings by
    /// line, so the block-anchored one (the `unit 683` line) comes first here.
    #[test]
    fn a_flagged_taxer_loses_to_the_last_of_two_written_orders() {
        let findings = two_month_long(check_months(
            vec![region(vec![taxing_by_flag(unit("683"))])],
            "unit 683\nMOVE N\nWORK\n",
        ));
        assert_eq!(findings.len(), 2, "{findings:?}");
        assert_eq!(findings[0].line, Some(1));
        assert_eq!(
            findings[0].message,
            "set to tax every month, but WORK spends the month instead, so it will not tax"
        );
        assert_eq!(findings[1].line, Some(2));
        assert_eq!(
            findings[1].message,
            "WORK replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
    }

    /// The deliberate divergence from `check_idle_units`, which bails on an unread line. That
    /// check claims a unit does *nothing*, which an unread line could falsify; two readable
    /// month-long orders are two whatever else the block holds.
    #[test]
    fn an_unread_order_line_does_not_silence_a_second_month_long_order() {
        let finding = only(two_month_long(check_months(
            vec![region(vec![unit("683")])],
            "unit 683\nMOVE N\nSTUDY Combat\nFLIBBERTIGIBBET 4021\n",
        )));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "STUDY replaces this MOVE as the unit's month-long order, so this MOVE will not run"
        );
    }

    // --- a losing month order has no effects (ah-rzkm) ----------------------------------------

    /// The effective intents of one unit, built the way `review_turn` and `item_effects` both
    /// build them.
    fn effective_keywords(region: &ReportRegion, orders: &str, unit_id: &str) -> Vec<&'static str> {
        let ordered = OrderedUnits::read(orders);
        let rules = ruleset();
        let hex = hex_with_transfers(
            region,
            &ordered,
            &[],
            Some(&rules),
            &BTreeSet::new(),
            &BTreeSet::new(),
        );
        hex.find(unit_id)
            .expect("the unit is in the hex")
            .intents
            .iter()
            .map(|placed| placed.keyword)
            .collect()
    }

    fn all_keywords(region: &ReportRegion, orders: &str, unit_id: &str) -> Vec<&'static str> {
        let ordered = OrderedUnits::read(orders);
        let rules = ruleset();
        let hex = hex_with_transfers(
            region,
            &ordered,
            &[],
            Some(&rules),
            &BTreeSet::new(),
            &BTreeSet::new(),
        );
        hex.find(unit_id)
            .expect("the unit is in the hex")
            .all_intents
            .iter()
            .map(|placed| placed.keyword)
            .collect()
    }

    /// `rules/study` and `rules/produce`: each spends the unit's month, and the navigator's rule
    /// of 2026-09-03 is that the *last* month-long order replaces every earlier one. Chained
    /// `MOVE` lines are one claim (`rules/move`), and here they are not the last claim.
    #[test]
    fn earlier_month_claims_are_removed_and_only_the_final_one_is_retained() {
        let region = region(vec![unit("683")]);
        let orders = "unit 683\nMOVE N\nMOVE NE\nSTUDY Combat\nPRODUCE sword\n";

        assert_eq!(effective_keywords(&region, orders, "683"), vec!["PRODUCE"]);
        assert_eq!(
            all_keywords(&region, orders, "683"),
            vec!["MOVE", "MOVE", "STUDY", "PRODUCE"]
        );
    }

    /// An order that does not spend the month is never a claimant, so every one of them survives
    /// however the month is settled.
    #[test]
    fn effective_month_keeps_free_orders_and_only_the_final_single_line() {
        let region = region(vec![with_silver(unit("683"), 1_000)]);
        let orders = "unit 683\nBUILD Tower\nGIVE 5104 100 SILV\nPRODUCE sword\n";

        assert_eq!(
            effective_keywords(&region, orders, "683"),
            vec!["GIVE", "PRODUCE"]
        );
    }

    /// `rules/move`: "Multiple MOVE orders given by one unit will chain together." A free order
    /// written between them does not interrupt the chain, so the whole chain wins together.
    #[test]
    fn effective_month_keeps_a_consecutive_movement_chain() {
        let region = region(vec![with_silver(unit("683"), 1_000)]);
        let orders = "unit 683\nMOVE N\nGIVE 5104 100 SILV\nMOVE S\n";

        assert_eq!(
            effective_keywords(&region, orders, "683"),
            vec!["MOVE", "GIVE", "MOVE"]
        );
    }

    /// Another month-long order between two `MOVE` lines does interrupt the chain: the navigator
    /// chose that only the final `MOVE` survives, rather than reviving the first around the
    /// replaced `STUDY`.
    #[test]
    fn effective_month_breaks_a_chain_around_another_month_long_order() {
        let region = region(vec![unit("683")]);
        let orders = "unit 683\nMOVE N\nSTUDY Combat\nMOVE S\n";

        assert_eq!(effective_keywords(&region, orders, "683"), vec!["MOVE"]);
        assert_eq!(
            all_keywords(&region, orders, "683"),
            vec!["MOVE", "STUDY", "MOVE"]
        );
    }

    /// `rules/produce`: PRODUCE spends the month, so a PRODUCE a later STUDY replaces never runs,
    /// and a warning about the skill it would have needed is advice about an order that will not
    /// happen.
    #[test]
    fn a_losing_produce_emits_only_the_month_conflict_warning() {
        let findings = check_months(
            vec![region(vec![with_silver(unit("683"), 100)])],
            "unit 683\nPRODUCE sword\nSTUDY Combat\n",
        );
        assert_eq!(
            codes(&findings),
            vec!["two-month-long-orders"],
            "{findings:?}"
        );
        let finding = only(findings);
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "STUDY replaces this PRODUCE as the unit's month-long order, so this PRODUCE will \
             not run"
        );
    }

    /// A losing PRODUCE is not merely unwarned about - it does nothing at all, so neither the
    /// SILVER forecast nor the ITEMS column may show its materials leaving or its goods arriving.
    #[test]
    fn a_losing_produce_moves_no_materials_and_creates_no_goods() {
        let smith = with_item(
            with_skill(with_silver(unit("683"), 1_000), "WEAP", 1),
            20,
            "iron",
            "IRON",
        );
        let report = report(vec![region(vec![smith])]);
        let orders = "unit 683\nPRODUCE sword\nSTUDY Combat\n";

        let review = review_turn(&report, orders, Some(&ruleset()), CheckOptions::default());
        let forecast = review
            .silver
            .iter()
            .find(|row| row.unit_id == "683")
            .expect("the unit is priced");
        assert_eq!(forecast.produced, 0, "{forecast:?}");
        assert_eq!(forecast.production_wanted, 0, "{forecast:?}");

        let effects = item_effects(&report, orders, Some(&ruleset()));
        let moved = effects
            .get("683")
            .map(|unit| unit.moved.clone())
            .unwrap_or_default();
        assert!(
            !moved
                .iter()
                .any(|movement| movement.tag == "SWOR" || movement.tag == "IRON"),
            "{moved:?}"
        );
    }

    /// The navigator's own example, on the projection side: `BUILD` then `PRODUCE`, where the
    /// `BUILD` is the replaced order. `BUILD` is priced through a call path of its own, so
    /// [`a_losing_produce_moves_no_materials_and_creates_no_goods`] does not cover it - a replaced
    /// `BUILD` must record no `BuildSpend` and move none of the structure's material.
    #[test]
    fn a_replaced_build_records_neither_material_nor_spend() {
        let builder = in_structure(
            with_skill(
                with_item(
                    with_men(with_silver(unit("900"), 1_000), 10),
                    120,
                    "wood",
                    "WOOD",
                ),
                "BUIL",
                3,
            ),
            "4",
        );
        let hex_region = ReportRegion {
            structures: vec![unfinished_building("4")],
            ..region(vec![builder])
        };
        let report = report(vec![hex_region]);

        let replaced = item_effects(&report, "unit 900\nBUILD\nENTERTAIN\n", Some(&ruleset()))
            .get("900")
            .cloned()
            .unwrap_or_default();
        assert!(
            replaced.built.is_empty(),
            "a replaced BUILD spends nothing: {:?}",
            replaced.built
        );
        assert!(
            !replaced.moved.iter().any(|movement| movement.tag == "WOOD"),
            "a replaced BUILD moves no material: {:?}",
            replaced.moved
        );

        // The reverse order, so the assertions above are about the replacement and not about a
        // fixture that never built anything.
        let winning = item_effects(&report, "unit 900\nENTERTAIN\nBUILD\n", Some(&ruleset()))
            .get("900")
            .cloned()
            .unwrap_or_default();
        assert_eq!(winning.built.len(), 1, "{:?}", winning.built);
        assert_eq!(winning.built[0].tag, "WOOD");
        assert!(
            winning
                .moved
                .iter()
                .any(|movement| movement.tag == "WOOD" && movement.delta < 0),
            "the winning BUILD does consume its material: {:?}",
            winning.moved
        );
    }

    /// `rules/produce`: PRODUCE spends the month, so a PRODUCE that lost it trades in no region
    /// and cannot push the faction past its allowance.
    #[test]
    fn a_losing_produce_does_not_spend_a_trade_region() {
        let regions = vec![
            region_at("1:7,53", 7, 53, vec![with_silver(unit("5"), 1_000)]),
            region_at("1:8,53", 8, 53, vec![unit("6")]),
            region_at("1:9,53", 9, 53, vec![unit("7")]),
        ];
        // Two regions genuinely produce, which is the allowance; the third unit's PRODUCE lost
        // its month to the STUDY below it.
        let orders = "unit 6\nPRODUCE grain\nunit 7\nPRODUCE grain\n\
                      unit 5\nPRODUCE grain\nSTUDY Combat\n";
        let findings = check_trade(regions, orders, "Trade Regions", 2);

        assert!(
            !findings
                .iter()
                .any(|finding| finding.code == codes::TOO_MANY_TRADE_REGIONS),
            "{findings:?}"
        );
    }

    /// `rules/study`: a replaced STUDY line never runs, so it asks for no quartermaster place.
    #[test]
    fn a_losing_quartermaster_study_does_not_spend_the_allowance() {
        let findings = quartermasters(
            vec![region(vec![unit("5"), unit("6")])],
            "unit 5\nSTUDY QUAM\nunit 6\nSTUDY QUAM\nMOVE N\n",
            1,
            2,
        );

        assert!(
            !findings
                .iter()
                .any(|finding| finding.code == codes::TOO_MANY_QUARTERMASTERS),
            "{findings:?}"
        );
    }

    /// The normalization and the conflict warning share one TEACH eligibility decision, taken
    /// after this month's transfers. A unit of non-leaders certainly cannot teach
    /// (`rules/teach`), so its TEACH claims no month and the STUDY below it is the order that
    /// runs.
    #[test]
    fn a_teach_order_that_cannot_run_does_not_discard_the_later_month_order() {
        let teacher = with_skill(with_silver(one_human("500"), 1_000), "COMB", 3);
        let student = with_silver(one_human("700"), 1_000);
        let findings = check_months(
            vec![region(vec![teacher, student])],
            "unit 500\nTEACH 700\nSTUDY Combat\nunit 700\nSTUDY Combat\n",
        );

        assert_eq!(
            effective_keywords(
                &region(vec![
                    with_skill(with_silver(one_human("500"), 1_000), "COMB", 3),
                    with_silver(one_human("700"), 1_000),
                ]),
                "unit 500\nTEACH 700\nSTUDY Combat\n",
                "500",
            ),
            vec!["TEACH", "STUDY"],
            "the TEACH claims no month, so the STUDY is the order that runs"
        );
        assert!(
            codes(&findings).contains(&codes::TEACHER_CANNOT_TEACH.as_str()),
            "{findings:?}"
        );
        assert!(
            !findings
                .iter()
                .any(|finding| finding.code == codes::TWO_MONTH_LONG_ORDERS),
            "{findings:?}"
        );
    }

    /// One TEACH eligibility decision, not two, and taken on the right side of the market phase.
    ///
    /// `rules/sequenceofevents` resolves `BUY` before the month-long phase that teaches, so a
    /// unit of leaders that buys orcs is no longer all-leaders when it teaches: its `TEACH`
    /// certainly cannot run, claims no month, and the `STUDY` below it is the order that does.
    /// The alternative - the filter reading the pre-recruit state while `check_teacher` reads the
    /// post-recruit one - tells the unit in one breath that it cannot teach and that the teaching
    /// it cannot do spent its month.
    #[test]
    fn a_teach_the_market_phase_disqualifies_does_not_claim_the_month() {
        let mut hex = region(vec![
            with_leaders(with_skill(with_silver(unit("500"), 100_000), "COMB", 3), 3),
            with_silver(unit("700"), 1_000),
        ]);
        hex.for_sale.push(MarketItem {
            amount: 40,
            name: "orc".to_string(),
            tag: "ORC".to_string(),
            price: 10,
        });
        let orders = "unit 500\nTEACH 700\nBUY 5 orc\nSTUDY Combat\nunit 700\nSTUDY Combat\n";

        let findings = check_months(vec![hex], orders);
        let told: Vec<&str> = findings
            .iter()
            .filter(|finding| finding.unit_id.as_deref() == Some("500"))
            .map(|finding| finding.code.as_str())
            .collect();

        assert!(
            told.contains(&codes::TEACHER_CANNOT_TEACH.as_str()),
            "the orcs it bought are already there when it teaches: {findings:?}"
        );
        assert!(
            !told.contains(&codes::TWO_MONTH_LONG_ORDERS.as_str()),
            "a TEACH that cannot run claims no month, so the STUDY is not discarded: {findings:?}"
        );
    }

