    // --- FORM aliases -------------------------------------------------------------------------

    #[test]
    // Both formed units are given nobody, so `ah-ndp9`'s F2 rule leaves them unjudged and `only`
    // still sees exactly one finding.
    fn a_form_number_used_twice_by_one_unit_warns_on_the_second() {
        let finding = only(check(
            vec![region(vec![unit("5")])],
            "unit 5\nFORM 1\nSTUDY FORC\nEND\nFORM 1\nSTUDY FORC\nEND\n",
        ));

        assert_eq!(finding.code, codes::FORM_ALIAS_REUSED);
        assert_eq!(finding.unit_id, Some("5".to_string()));
        assert_eq!(finding.line, Some(5));
        assert_eq!(
            finding.message,
            "FORM 1 again: line 2 already forms NEW 1 in this hex; the rules say not to reuse an alias here"
        );
    }

    /// A zero alias is a syntax error (`grammar::Arg::Alias`), so it forms nothing and there is
    /// no second FORM to warn about - one complaint on the line, not two about different things.
    #[test]
    fn a_zero_alias_forms_no_unit_and_earns_no_finding() {
        assert_eq!(
            check(
                vec![region(vec![unit("5")])],
                "unit 5\nFORM 0\nEND\nFORM 0\nEND\n",
            ),
            vec![],
        );
        assert_eq!(
            check(
                vec![region(vec![unit("5")])],
                "unit 5\nFORM 0\nEND\nGIVE NEW 0 1 SILV\n",
            ),
            vec![],
        );
    }

    #[test]
    fn three_copies_give_two_warnings_each_naming_the_first() {
        let findings = check(
            vec![region(vec![unit("5")])],
            "unit 5\nFORM 1\nEND\nFORM 1\nEND\nFORM 1\nEND\n",
        );

        assert_eq!(
            findings.iter().map(|f| f.line).collect::<Vec<_>>(),
            vec![Some(4), Some(6)]
        );
        for finding in &findings {
            assert!(
                finding.message.contains("line 2 already forms NEW 1"),
                "both should name the first use: {}",
                finding.message
            );
        }
    }

