    #[test]
    /// One finding, not two: the TAKE from a number the report never prints is still a mistake, and
    /// the GIVE to one is not (`ah-66yi`). The GIVE to a unit shown *elsewhere* is, which is what
    /// the second unit here holds onto.
    fn both_a_give_and_a_take_on_one_unit_are_two_findings() {
        let elsewhere = ReportRegion {
            region_id: "1:9,53".to_string(),
            ..region(vec![unit("4427")])
        };
        let findings = check(
            vec![region(vec![unit("4426")]), elsewhere],
            "unit 4426\nGIVE 4427 50 SILV\nTAKE FROM 16586 50 SILV\n",
        );

        assert_eq!(
            findings.iter().map(|f| f.code).collect::<Vec<_>>(),
            vec![codes::GIVE_TARGET_NOT_HERE, codes::GIVE_TARGET_NOT_HERE]
        );
        assert_eq!(
            findings.iter().map(|f| f.line).collect::<Vec<_>>(),
            vec![Some(2), Some(3)]
        );
        assert!(findings[0].message.contains("given to"));
        assert!(findings[1].message.contains("taken from"));
    }

    // --- refused transfers ----------------------------------------------------------------------

    /// The fixture's item *names* are load-bearing: `counted_item` takes the plural from
    /// `plurals_in`, which reads the report's own name for anything held above one - so this must
    /// be built with the plural spellings ("lions", "wolves") or the sentence comes out singular.
    #[test]
    fn a_gift_of_monsters_the_game_refuses_says_what_stays_and_what_goes() {
        let giver = with_item(
            with_item(
                with_item(unit("900"), 20, "lions", "LION"),
                3,
                "wolves",
                "WOLF",
            ),
            1,
            "skeleton",
            "SKEL",
        );
        let finding = only(check(
            vec![region(vec![giver, unit("901")])],
            "unit 900\nGIVE 901 ALL MONSTERS\n",
        ));

        assert_eq!(finding.code, codes::ITEMS_CANNOT_BE_GIVEN);
        assert_eq!(finding.unit_id, Some("900".to_string()));
        assert_eq!(finding.line, Some(2));
        assert_eq!(
            finding.message,
            "20 lions and 3 wolves cannot be given away, so this order moves only 1 skeleton"
        );
    }

