        let exotic = with_item(overloaded, 1, "thingummy", "ZZZZ");
        let finding = only(check(vec![region(vec![exotic])], "unit 12054\nMOVE S S\n"));
        assert_eq!(finding.code.as_str(), "unit-overloaded");
