    #[test]
    fn a_gift_of_all_men_uses_what_the_giver_actually_holds() {
        let receiver = with_men(unit("2200"), 5);
        let giver = with_skill_pts(men_holder("1010", 10), "LUMB", 450);

        let all_orders = "unit 1010\nGIVE 2200 ALL HUMN\n";
        let all_ordered = OrderedUnits::read(all_orders);
        let all_region = region(vec![receiver.clone(), giver.clone()]);
        let all_hex = hex_after_gifts(&all_region, &all_ordered);
        // (5*0 + 10*450) / 15 = 300, level 4.
        assert_eq!(all_hex.find("2200").unwrap().skill_level("LUMB"), Some(4));

        let except_orders = "unit 1010\nGIVE 2200 ALL HUMN EXCEPT 8\n";
        let except_ordered = OrderedUnits::read(except_orders);
        let except_region = region(vec![receiver, giver]);
        let except_hex = hex_after_gifts(&except_region, &except_ordered);
        // Only 2 move: (5*0 + 2*450) / 7 = 128, level 2.
        assert_eq!(
            except_hex.find("2200").unwrap().skill_level("LUMB"),
            Some(2)
        );
    }

    #[test]
    fn two_gifts_into_one_unit_are_merged_in_document_order() {
        let receiver = with_skill_pts(with_men(unit("2200"), 5), "LUMB", 180);
        let skilled_giver = with_skill_pts(men_holder("1010", 3), "LUMB", 30);
        let unskilled_giver = men_holder("1020", 4);

        // (5*180 + 3*30) / 8 = 123 (level 2), then (8*123 + 4*0) / 12 = 82 (level 1).
        let orders = "unit 1010\nGIVE 2200 3 HUMN\nunit 1020\nGIVE 2200 4 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let first_region = region(vec![
            receiver.clone(),
            skilled_giver.clone(),
            unskilled_giver.clone(),
        ]);
        let hex = hex_after_gifts(&first_region, &ordered);
        assert_eq!(hex.find("2200").unwrap().skill_level("LUMB"), Some(1));

        // Reversed: (5*180 + 4*0) / 9 = 100 (level 2), then (9*100 + 3*30) / 12 = 82 (level 1) -
        // the arithmetic commutes here, so the order of the two blocks does not matter.
        let reversed_orders = "unit 1020\nGIVE 2200 4 HUMN\nunit 1010\nGIVE 2200 3 HUMN\n";
        let reversed_ordered = OrderedUnits::read(reversed_orders);
        let reversed_region = region(vec![receiver, skilled_giver, unskilled_giver]);
        let reversed_hex = hex_after_gifts(&reversed_region, &reversed_ordered);
        assert_eq!(
            reversed_hex.find("2200").unwrap().skill_level("LUMB"),
            Some(1)
        );
    }

    /// A unit that receives men this month, and then re-gives some of them onward in the same
    /// hex, must be able to give what it just received - not be clamped to what the *report*
    /// showed it holding before any gift arrived. Caught by review on this PR: the receiver's own
    /// running `held`/`men` were only ever credited by later reads, never by an arrival, so a
    /// re-gift moved 0 and the downstream unit was silently judged on stale figures.
    #[test]
    fn men_received_this_month_can_be_re_given_within_the_same_hex() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let middle = with_men(unit("2200"), 0);
        let receiver = with_men(unit("3300"), 0);

        let orders = "unit 1010\nGIVE 2200 3 HUMN\nunit 2200\nGIVE 3300 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, middle, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert_eq!(hex.find("3300").unwrap().skill_level("LUMB"), Some(1));
    }

    #[test]
    fn a_gift_of_men_leaves_the_giver_untouched() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let receiver = unit("2200");
        let orders = "unit 1010\nGIVE 2200 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert_eq!(
            hex.find("1010").unwrap().skill_level("LUMB"),
            Some(level_for_points(30))
        );
    }

    #[test]
    fn giving_men_to_nobody_takes_them_off_the_giver() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let orders = "unit 1010\nGIVE 0 5 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver]);

        // Chiefly that this does not panic: there is no receiver to credit.
        let hex = hex_after_gifts(&region, &ordered);
        assert_eq!(hex.find("1010").unwrap().skill_level("LUMB"), Some(1));
    }

    /// `rules/magic`: "mages may not GIVE men at all". The semantic projection must retain them
    /// too, or the units table, maintenance, production and the warnings disagree about one order.
    ///
    /// It deliberately records no `RefusedTransfer`: this bead adds no diagnostic, so
    /// `check_refused_transfers` says nothing new about the invalid order.
    #[test]
    fn a_mage_gift_keeps_men_and_skills_in_the_semantic_projection() {
        let giver = with_skill_pts(with_leaders(unit("1010"), 2), "FORC", 30);
        let receiver = men_holder("2200", 1);
        let orders = "unit 1010\nGIVE 2200 2 LEAD\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        let mage = hex.find("1010").expect("the mage is in this hex");
        assert_eq!(mage.men_after_orders, 2, "the mage keeps its two leaders");
        assert!(
            matches!(mage.holdings_after_gifts, HoldingsAfterGifts::Unchanged),
            "nothing left the mage: {:?}",
            mage.holdings_after_gifts
        );
        assert!(
            matches!(mage.skills_after_gifts, SkillsAfterGifts::Unchanged),
            "and its own skills are untouched: {:?}",
            mage.skills_after_gifts
        );
        assert!(
            mage.refused_transfers.is_empty(),
            "the refusal is silent - this bead adds no diagnostic: {:?}",
            mage.refused_transfers
        );

        let receiver = hex.find("2200").expect("the receiver is in this hex");
        assert_eq!(receiver.men_after_orders, 1, "and nobody arrived");
        assert!(matches!(
            receiver.holdings_after_gifts,
            HoldingsAfterGifts::Unchanged
        ));
        assert!(matches!(
            receiver.skills_after_gifts,
            SkillsAfterGifts::Unchanged
        ));
    }

    #[test]
    fn a_gift_of_goods_is_not_a_gift_of_men() {
        let giver = with_item(
            with_skill_pts(unit("1010"), "LUMB", 30),
            10,
            "swords",
            "SWOR",
        );
        let receiver = unit("2200");
        let orders = "unit 1010\nGIVE 2200 10 SWOR\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert!(matches!(
            hex.find("1010").unwrap().skills_after_gifts,
            SkillsAfterGifts::Unchanged
        ));
        assert!(matches!(
            hex.find("2200").unwrap().skills_after_gifts,
            SkillsAfterGifts::Unchanged
        ));
    }

    /// `rules/take`: "works just like the GIVE order, except that the direction of transfer is
    /// reversed" - so a TAKE of men is judged on what actually arrives, exactly as a GIVE is,
    /// rather than left unjudged the way it was before `effects.rs` modelled a TAKE of men at
    /// all (`ah-dxfd.1`). Renamed from `men_taken_rather_than_given_leave_the_taker_unjudged`.
    #[test]
    fn men_taken_rather_than_given_are_judged_on_what_arrives() {
        let orders = "unit 1010\nPRODUCE WOOD\nTAKE FROM 2200 5 HUMN\n";

        let skilled = check_turn(
            &report(vec![region(vec![
                unit("1010"),
                // Points high enough that the merged average still clears WOOD's level-1
                // threshold: (1 man at 0 + 5 arriving at 180) / 6 = 150, level 2.
                with_skill_pts(men_holder("2200", 5), "LUMB", 180),
            ])]),
            orders,
            Some(&ruleset()),
            CheckOptions::default(),
        );
        assert!(
            !codes(&skilled).contains(&"produce-without-skill"),
            "the taken men know lumberjack, so the taker is judged and found competent: \
             {skilled:?}"
        );

        // The control: without the skill, the taker is still judged - not merely left quiet -
        // and found lacking. That is what proves the absence above is a real judgement.
        let unskilled = check_turn(
            &report(vec![region(vec![unit("1010"), men_holder("2200", 5)])]),
            orders,
            Some(&ruleset()),
            CheckOptions::default(),
        );
        assert!(
            codes(&unskilled).contains(&"produce-without-skill"),
            "the taken men bring no lumberjack: {unskilled:?}"
        );
    }

    /// Renamed from `a_gift_of_a_whole_class_leaves_the_receiver_unjudged`: `MAN`/`MEN` is
    /// `classify_unit`'s own filter and needs no classifying by this pass at all, so a gift of it
    /// is judged on what actually arrives exactly as a named tag is (`ah-dxfd.1`).
    #[test]
    fn a_gift_of_a_whole_class_of_men_is_judged_on_what_arrives() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let receiver = unit("2200");
        let orders = "unit 1010\nGIVE 2200 ALL MEN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert!(
            matches!(
                hex.find("2200").unwrap().skills_after_gifts,
                SkillsAfterGifts::Merged(_)
            ),
            "GIVE ALL MEN can now be judged: {:?}",
            hex.find("2200").unwrap().skills_after_gifts
        );
        // 1 man with none merges with 5 arriving at (30) -> (1*0 + 5*30) / 6 = 25, level 0.
        assert_eq!(hex.find("2200").unwrap().skill_level("LUMB"), Some(0));
    }

    #[test]
    fn a_gift_of_a_class_that_holds_no_people_judges_normally() {
        let giver = with_item(unit("1010"), 3, "swords", "SWOR");
        let receiver = unit("2200");
        let orders = "unit 1010\nGIVE 2200 ALL WEAPONS\nunit 2200\nPRODUCE WOOD\n";

        let findings = check_turn(
            &report(vec![region(vec![giver, receiver])]),
            orders,
            Some(&ruleset()),
            CheckOptions::default(),
        );

        assert!(
            codes(&findings).contains(&"produce-without-skill"),
            "{findings:?}"
        );
    }

    /// `apply_transfers` is the one walk with a running holding per unit, so it is the only place
    /// that can say what a *later* line on the same unit would still have found - `RefusedTransfer`
    /// is written here and read by `check_refused_transfers`, never recomputed.
    #[test]
    fn a_refused_gift_is_recorded_against_the_line_that_named_it() {
        let giver = with_item(
            with_item(unit("900"), 20, "lions", "LION"),
            1,
            "skeleton",
            "SKEL",
        );
        let receiver = unit("901");
        let orders = "unit 900\nGIVE 901 ALL MONSTERS\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        let giver = hex.find("900").expect("the giver is still in the hex");
        assert_eq!(
            giver.refused_transfers,
            vec![RefusedTransfer {
                line: 2,
                is_give: true,
                refused: vec![("LION".to_string(), 20)],
                refused_to_another_faction: vec![],
                into_a_mage: vec![],
                mage_id: None,
                moving: vec![("SKEL".to_string(), 1)],
            }]
        );
    }

    #[test]
    fn an_inexact_headcount_leaves_the_receiver_unjudged() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let mut receiver = unit("2200");
        receiver.men_estimated = true;
        let orders = "unit 1010\nGIVE 2200 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert!(matches!(
            hex.find("2200").unwrap().skills_after_gifts,
            SkillsAfterGifts::Unknowable
        ));
    }

    /// The giver's own headcount does not enter the arithmetic at all - what arrives is its
    /// points per man, times the amount the order states - so an estimated giver still lets a
    /// receiver with an exact headcount be judged normally.
    #[test]
    fn the_givers_own_estimated_headcount_does_not_doubt_the_receiver() {
        let mut giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        giver.men_estimated = true;
        let receiver = unit("2200");
        let orders = "unit 1010\nGIVE 2200 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        // Judged normally - the merge is computed, not silenced - regardless of what its result
        // is; the receiver started with its own man and no lumberjack, so the arriving points
        // are diluted to level 0 rather than kept at the giver's level 1.
        assert!(matches!(
            hex.find("2200").unwrap().skills_after_gifts,
            SkillsAfterGifts::Merged(_)
        ));
        assert_eq!(hex.find("2200").unwrap().skill_level("LUMB"), Some(0));
    }

    #[test]
    fn doubt_carries_to_the_next_unit_along() {
        let middle = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let receiver = unit("2200");
        // "999" is not in this region at all - a unit this hex genuinely does not show, which
        // still doubts the taker under `resolve_give_target`'s `GiveTarget::Nowhere` even now
        // that a TAKE of men can otherwise be judged (`ah-dxfd.1`).
        let orders = "unit 1010\nTAKE FROM 999 5 HUMN\nGIVE 2200 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![middle, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert!(matches!(
            hex.find("2200").unwrap().skills_after_gifts,
            SkillsAfterGifts::Unknowable
        ));
    }

    /// `apply_transfers` writes `men_after_orders`/`arrivals` for every unit its walk touches,
    /// giver and receiver both - `arrivals` counts arrivals only, never netted against men the
    /// same unit gave away.
    #[test]
    fn a_gift_of_men_moves_both_counters() {
        let giver = with_skill_pts(men_holder("1010", 5), "LUMB", 30);
        let receiver = with_men(unit("2200"), 1);
        let orders = "unit 1010\nGIVE 2200 3 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let region = region(vec![giver, receiver]);
        let hex = hex_after_gifts(&region, &ordered);

        assert_eq!(hex.find("2200").unwrap().men_after_orders, 4);
        assert_eq!(hex.find("2200").unwrap().arrivals.total(), 3);
        assert_eq!(hex.find("1010").unwrap().men_after_orders, 2);
        assert_eq!(hex.find("1010").unwrap().arrivals.total(), 0);
    }

    /// `Arrivals` tells a gift from a take, because `arrivals-lower-a-skill` names the order the
    /// player wrote, and the three orders are three different words in its message.
    #[test]
    fn a_gift_and_a_take_are_counted_apart() {
        let region = region(vec![
            men_holder("1010", 5),
            men_holder("2200", 5),
            men_holder("3100", 10),
        ]);
        let orders = "unit 1010\nGIVE 3100 3 HUMN\nunit 3100\nTAKE FROM 2200 2 HUMN\n";
        let ordered = OrderedUnits::read(orders);
        let hex = hex_after_gifts(&region, &ordered);

        assert_eq!(
            hex.find("3100").unwrap().arrivals,
            Arrivals {
                given: 3,
                taken: 2,
                bought: 0,
            }
        );
        assert_eq!(hex.find("3100").unwrap().arrivals.total(), 5);
        // A unit that only gave men away has no arrivals.
        assert_eq!(hex.find("1010").unwrap().arrivals.total(), 0);
    }

    // --- arrivals-lower-a-skill (ah-z73s.4) ------------------------------------------------------

    /// The finding under `codes::ARRIVALS_LOWER_A_SKILL`, or a panic naming every finding the
    /// fixture raised - the fixture may raise other advisories, and this bead must not become the
    /// reason they are silenced.
    fn arrivals_finding(findings: &[Finding]) -> &Finding {
        findings
            .iter()
            .find(|finding| finding.code == codes::ARRIVALS_LOWER_A_SKILL)
            .unwrap_or_else(|| panic!("{findings:?}"))
    }

    #[test]
    fn a_gift_that_lowers_a_skill_is_reported() {
        let region = region(vec![
            men_holder("1010", 5),
            with_named_skill_pts(men_holder("3100", 10), "lumberjack", "LUMB", 180),
        ]);
        let orders = "unit 1010\nGIVE 3100 5 HUMN\n";

        let findings = check(vec![region], orders);
        let finding = arrivals_finding(&findings);

        assert_eq!(
            finding.message,
            "giving 5 men to this unit lowers its lumberjack from 3 to 2"
        );
        assert_eq!(finding.unit_id.as_deref(), Some("3100"));
        assert!(finding.line.is_none());
        assert!(finding.column_start.is_none());
    }

    #[test]
    fn a_recruit_that_lowers_a_skill_is_reported() {
        let crew = with_silver(
            with_named_skill_pts(men_holder("900", 10), "lumberjack", "LUMB", 30),
            400,
        );
        let region = ReportRegion {
            for_sale: vec![MarketItem {
                amount: 20,
                name: "men".to_string(),
                tag: "HUMN".to_string(),
                price: 38,
            }],
            ..region(vec![crew])
        };
        let orders = "unit 900\nBUY 4 HUMN\n";

        let findings = check(vec![region], orders);
        let finding = arrivals_finding(&findings);

        assert_eq!(
            finding.message,
            "buying 4 men into this unit lowers its lumberjack from 1 to 0"
        );
    }

    #[test]
    fn a_take_that_lowers_a_skill_names_the_take() {
        let region = region(vec![
            men_holder("1010", 5),
            with_named_skill_pts(men_holder("3100", 10), "lumberjack", "LUMB", 180),
        ]);
        let orders = "unit 3100\nTAKE FROM 1010 5 HUMN\n";

        let findings = check(vec![region], orders);
        let finding = arrivals_finding(&findings);

        assert_eq!(
            finding.message,
            "taking 5 men into this unit lowers its lumberjack from 3 to 2"
        );
    }

    #[test]
    fn men_from_every_route_are_named_in_one_finding() {
        let region = ReportRegion {
            for_sale: vec![MarketItem {
                amount: 20,
                name: "men".to_string(),
                tag: "HUMN".to_string(),
                price: 38,
            }],
            ..region(vec![
                men_holder("1010", 5),
                men_holder("2200", 2),
                with_silver(
                    with_named_skill_pts(men_holder("3100", 10), "lumberjack", "LUMB", 180),
                    400,
                ),
            ])
        };
        let orders = "unit 1010\nGIVE 3100 5 HUMN\nunit 3100\nTAKE FROM 2200 2 HUMN\nBUY 4 HUMN\n";

        let findings = check(vec![region], orders);
        let matching: Vec<&Finding> = findings
            .iter()
            .filter(|finding| finding.code == codes::ARRIVALS_LOWER_A_SKILL)
            .collect();

        assert_eq!(matching.len(), 1, "{findings:?}");
        assert_eq!(
            matching[0].message,
            "giving 5 men to this unit, taking 2 more and buying 4 more lowers its lumberjack \
             from 3 to 1"
        );
    }

    #[test]
